package vn.edu.thuyetminh.support;

import java.io.IOException;
import java.io.InputStream;

import org.springframework.core.io.ClassPathResource;

public final class AudioFixtures {

    private AudioFixtures() {
    }

    /** Valid WAV generated by infra/scripts/make_demo_audio.py (tones, not speech). */
    public static byte[] wav(String lang) {
        try (InputStream in = new ClassPathResource("demo-audio/demo-" + lang + ".wav").getInputStream()) {
            return in.readAllBytes();
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }
}
